<?php
require_once __DIR__ . '/../bootstrap.php'; require_admin();$q=trim($_GET['q']??'');$categoryId=filter_input(INPUT_GET,'category_id',FILTER_VALIDATE_INT);$sql="SELECT p.*,c.name AS category_name FROM products p LEFT JOIN categories c ON c.id=p.category_id WHERE 1=1";$params=[];if($q!==''){$sql.=' AND (p.name LIKE ? OR p.brand LIKE ?)';$params[]="%$q%";$params[]="%$q%";}if($categoryId){$sql.=' AND p.category_id=?';$params[]=$categoryId;}$sql.=' ORDER BY p.id DESC';$st=$conn->prepare($sql);$st->execute($params);$rows=$st->fetchAll(PDO::FETCH_ASSOC);$categories=$conn->query('SELECT id,name FROM categories ORDER BY name')->fetchAll(PDO::FETCH_ASSOC);
admin_header('Quản lý sản phẩm'); ?>
<div class="card"><div class="toolbar"><form class="search" method="get"><input class="form-control" name="q" placeholder="Tìm tên hoặc thương hiệu..." value="<?= h($q) ?>"><select class="form-control" name="category_id" style="width:auto"><option value="">Tất cả danh mục</option><?php foreach($categories as $c): ?><option value="<?= (int)$c['id'] ?>" <?= $categoryId===(int)$c['id']?'selected':'' ?>><?= h($c['name']) ?></option><?php endforeach; ?></select><button class="btn" type="submit">Lọc</button></form><a class="btn btn-success" href="<?= h(admin_url('products/create.php')) ?>">+ Thêm sản phẩm</a></div><div class="table-wrap"><table><thead><tr><th>ID</th><th>Ảnh</th><th>Sản phẩm</th><th>Danh mục</th><th>Giá</th><th>Tồn kho</th><th>Thao tác</th></tr></thead><tbody><?php if(!$rows): ?><tr><td colspan="7" class="empty">Không có sản phẩm phù hợp.</td></tr><?php else: foreach($rows as $p): ?><tr><td><?= (int)$p['id'] ?></td><td><?php if($p['image']): ?><img class="product-thumb" src="<?= h(site_url('image/'.rawurlencode(basename($p['image'])))) ?>" alt=""><?php else: ?>—<?php endif; ?></td><td><strong><?= h($p['name']) ?></strong><div class="text-muted"><?= h($p['brand']) ?></div></td><td><?= h($p['category_name']??'Chưa phân loại') ?></td><td><?= h(money($p['price'])) ?></td><td><?= (int)$p['stock'] ?></td><td><div class="actions"><a class="btn btn-small" href="<?= h(admin_url('products/edit.php?id='.(int)$p['id'])) ?>">Sửa</a><form method="post" action="<?= h(admin_url('products/delete.php')) ?>" onsubmit="return confirm('Bạn chắc chắn muốn xóa sản phẩm này?');"><input type="hidden" name="csrf_token" value="<?= h(csrf_token()) ?>"><input type="hidden" name="id" value="<?= (int)$p['id'] ?>"><button class="btn btn-danger btn-small" type="submit">Xóa</button></form></div></td></tr><?php endforeach; endif; ?></tbody></table></div></div><?php admin_footer(); ?>
